                for cc in range(3):
                    val = grid[block_r * 3 + rr][block_c * 3 + cc]
                    if val not in [0, 5]:
                        cells.append(val)
            if cells:
                val_counts = Counter(cells)
                dominant = val_counts.most_common(1)[0][0]
                row_out.append(dominant)
            else:
                row_out.append(0)
        output.append(row_out)
    return output

